"""Estilo do painel (copiado do painel do Instituto do Sono, com a cor do Santa Clara)."""

CSS = '/* Painel administrativo — estilos isolados */\nhtml { scroll-behavior: smooth; scroll-padding-top: 70px; }\nbody { margin: 0; font-family: Inter, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; }\nbody { background: #f3f5f8; }\n.adm { --ink:#0f2a47; --blue:#0057c8; --mut:#64748b; --soft:#94a3b8; --line:#e6ebf1; --bg:#f3f5f8; --green:#16a34a; min-height: 100vh; background: var(--bg); color: #1e293b; font-size: 14px; }\n.adm h1, .adm h2, .adm h3, .adm h4 { color: var(--ink) !important; letter-spacing: -0.01em; text-align: left !important; margin: 0 !important; }\n.adm h1 { font-size: 26px !important; line-height: 1.2 !important; font-weight: 700 !important; }\n.adm h3 { font-size: 15px !important; line-height: 1.3 !important; font-weight: 700 !important; display: flex; align-items: center; gap: 8px; }\n.adm h4 { margin: 22px 0 10px !important; font-size: 11.5px !important; font-weight: 700 !important; color: var(--mut) !important; text-transform: uppercase; letter-spacing: .06em; }\n.adm code { padding: 2px 7px; border-radius: 5px; background: #eef2f6; font-size: 12px; color: var(--ink); }\n.adm a { color: var(--blue); }\n.adm b { font-weight: 600; color: var(--ink); }\n\n.adm-wrap { max-width: 1280px; margin: 0 auto; padding: 24px 20px 56px; display: grid; grid-template-columns: minmax(0, 1fr); gap: 16px; }\n.adm-kicker { margin: 0 0 2px; font-size: 11px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--mut); }\n.adm-period { margin: 6px 0 0; font-size: 13px; color: var(--mut); text-transform: none; }\n.adm-live { display: inline-flex; align-items: center; gap: 6px; color: var(--green); font-weight: 600; }\n.adm-live i { width: 8px; height: 8px; border-radius: 50%; background: #22c55e; box-shadow: 0 0 0 3px #22c55e33; }\n\n/* topo e filtros */\n.adm-top { display: flex; align-items: flex-end; justify-content: space-between; gap: 16px; flex-wrap: wrap; }\n.adm-filters { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }\n.adm-range { display: flex; gap: 2px; padding: 4px; border-radius: 12px; background: #fff; border: 1px solid var(--line); }\n.adm-range a { padding: 7px 13px; border-radius: 8px; color: #475569; font-weight: 600; font-size: 13px; text-decoration: none; white-space: nowrap; }\n.adm-range a:hover { background: #f1f5f9; }\n.adm-range a.on { background: var(--blue); color: #fff; }\n.adm-month { display: flex; gap: 4px; }\n.adm-month select { height: 40px; padding: 0 10px; border: 1px solid var(--line); border-radius: 10px; background: #fff; font: inherit; font-size: 13px; color: #334155; text-transform: capitalize; }\n.adm-month button, .adm-ghost { height: 40px; padding: 0 14px; border: 1px solid var(--line); border-radius: 10px; background: #fff; color: #475569; font: inherit; font-size: 13px; font-weight: 600; cursor: pointer; }\n.adm-month button { background: var(--blue); border-color: var(--blue); color: #fff; }\n.adm-test { height: 40px; display: inline-flex; align-items: center; padding: 0 12px; border: 1px dashed #cbd5e1; border-radius: 10px; color: var(--mut) !important; font-size: 12.5px; font-weight: 600; text-decoration: none; }\n.adm-test.on { border-style: solid; border-color: #f59e0b; background: #fffbeb; color: #b45309 !important; }\n\n/* navegação entre blocos */\n.adm-nav { position: sticky; top: 0; z-index: 20; display: flex; gap: 6px; padding: 10px 0; margin: 0 -4px; background: linear-gradient(var(--bg) 80%, transparent); overflow-x: auto; }\n.adm-nav a { flex-shrink: 0; padding: 7px 14px; border-radius: 999px; background: #fff; border: 1px solid var(--line); color: #475569; font-size: 13px; font-weight: 600; text-decoration: none; }\n.adm-nav a:hover { border-color: var(--blue); color: var(--blue); }\n\n.adm-group { margin: 22px 0 0 !important; padding-top: 6px; font-size: 19px !important; font-weight: 700 !important; display: flex; align-items: baseline; gap: 10px; flex-wrap: wrap; }\n.adm-group small { font-size: 12.5px; font-weight: 500; color: var(--soft); }\n\n/* cartões */\n.adm-card { padding: 20px 22px; border-radius: 16px; background: #fff; border: 1px solid var(--line); box-shadow: 0 1px 2px rgba(15,42,71,.04); min-width: 0; }\n.adm-card-head { display: flex; align-items: center; justify-content: space-between; gap: 12px; flex-wrap: wrap; margin-bottom: 16px; }\n.adm-grid2 { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px; align-items: start; }\n.adm-grid2.wide-left { grid-template-columns: minmax(0, 1.5fr) minmax(0, 1fr); }\n.adm-stack { display: grid; gap: 16px; min-width: 0; }\n.adm-empty { margin: 0; padding: 6px 0; color: var(--soft); }\n.adm-note { margin: 14px 0 0; font-size: 12px; line-height: 1.5; color: var(--soft); }\n.adm-note-card { background: #fffbeb; border-color: #fde68a; color: #92400e; line-height: 1.55; }\n.adm-note-card b { color: #78350f; }\n.adm-muted { color: var(--soft); font-size: 12px; }\n.adm-sub { display: block; margin-top: 2px; color: var(--soft); font-size: 11.5px; }\n.adm-count { display: inline-grid; place-items: center; min-width: 24px; height: 22px; padding: 0 7px; border-radius: 999px; background: #eef4fb; color: var(--blue); font-size: 12px; font-weight: 700; }\n.adm-ico { display: inline-grid; place-items: center; width: 34px; height: 34px; flex-shrink: 0; border-radius: 10px; background: #eef4fb; color: var(--blue); }\n.adm-ico.g { background: #dcfce7; color: var(--green); }\n\n/* indicadores principais */\n.adm-kpis { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 14px; }\n.adm-kpi { position: relative; display: flex; flex-direction: column; gap: 6px; padding: 18px 20px; border-radius: 16px; background: #fff; border: 1px solid var(--line); box-shadow: 0 1px 2px rgba(15,42,71,.04); }\n.adm-kpi-head { display: flex; align-items: center; gap: 10px; font-size: 13px; font-weight: 600; color: #475569; }\n.adm-kpi strong { margin-top: 6px; font-size: 34px; line-height: 1; color: var(--ink); font-weight: 700; letter-spacing: -.02em; }\n.adm-kpi small { font-size: 12.5px; color: var(--mut); }\n.adm-kpi.hl { border-color: #bbf7d0; background: linear-gradient(180deg, #fff 0%, #f0fdf4 100%); }\n.adm-kpi.hl strong { color: #15803d; }\n.adm-kpi .adm-delta { position: absolute; top: 18px; right: 18px; }\n.adm-delta { font-style: normal; padding: 3px 8px; border-radius: 999px; background: #f1f5f9; font-size: 11.5px; font-weight: 700; color: var(--mut); white-space: nowrap; }\n.adm-delta.up { background: #dcfce7; color: #15803d; }\n.adm-delta.down { background: #fee2e2; color: #b91c1c; }\n\n.adm-strip { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); border-radius: 16px; background: #fff; border: 1px solid var(--line); overflow: hidden; }\n.adm-strip > div { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; padding: 14px 18px; border-left: 1px solid var(--line); }\n.adm-strip > div:first-child { border-left: 0; }\n.adm-strip span { flex: 1 1 100%; font-size: 12px; color: var(--mut); font-weight: 600; }\n.adm-strip b { font-size: 20px; font-weight: 700; }\n\n.adm-insights { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 12px; }\n.adm-insight { display: flex; gap: 12px; align-items: flex-start; padding: 14px 16px; border-radius: 14px; background: #fff; border: 1px solid var(--line); min-width: 0; }\n.adm-insight > div { min-width: 0; display: grid; gap: 2px; }\n.adm-insight small { font-size: 11.5px; color: var(--mut); font-weight: 600; }\n.adm-insight b { font-size: 15px; line-height: 1.3; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n.adm-insight em { font-style: normal; font-size: 12px; color: var(--soft); }\n\n/* gráficos */\n.adm-legend { margin: 0; font-size: 12px; color: var(--mut); }\n.adm-legend i { display: inline-block; width: 10px; height: 10px; border-radius: 3px; margin: 0 5px 0 12px; vertical-align: -1px; }\n.adm-legend .lg-a { background: var(--blue); margin-left: 0; }\n.adm-legend .lg-b { background: #25D366; }\n.adm-cols { display: grid; gap: 4px; align-items: end; height: 200px; padding-top: 4px; border-bottom: 1px solid var(--line); }\n.adm-col { display: flex; flex-direction: column; align-items: center; justify-content: flex-end; height: 100%; gap: 4px; min-width: 0; position: relative; padding-bottom: 22px; }\n.adm-col-n { font-size: 10.5px; color: var(--mut); font-weight: 600; min-height: 13px; }\n.adm-col-bar { width: 100%; max-width: 36px; min-height: 2px; border-radius: 6px 6px 0 0; background: var(--blue); display: flex; align-items: flex-end; overflow: hidden; }\n.adm-col:hover .adm-col-bar { filter: brightness(1.15); }\n.adm-col-wa { width: 100%; background: #25D366; }\n.adm-col span { position: absolute; bottom: 4px; font-size: 10px; color: var(--soft); white-space: nowrap; }\n\n.adm-bars { list-style: none; margin: 0; padding: 0; display: grid; gap: 10px; }\n.adm-bars li { display: grid; grid-template-columns: minmax(90px, 40%) 1fr 52px; align-items: center; gap: 12px; }\n.adm-bar-label { font-size: 13px; color: #334155; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\n.adm-bar-track { height: 8px; border-radius: 99px; background: #eef2f6; overflow: hidden; }\n.adm-bar-fill { height: 100%; border-radius: 99px; background: var(--blue); min-width: 3px; }\n.adm-bars.green .adm-bar-fill { background: #25D366; }\n.adm-bar-value { text-align: right; font-size: 13px; font-weight: 700; color: var(--ink); }\n\n.adm-hours { display: grid; grid-template-columns: repeat(12, minmax(0, 1fr)); gap: 5px; }\n.adm-hours div { display: flex; flex-direction: column; align-items: center; gap: 1px; padding: 7px 0; border-radius: 8px; background: color-mix(in srgb, var(--blue) calc(var(--lvl, 0) * 100%), #eef2f6); color: #475569; }\n.adm-hours div.hot { color: #fff; }\n.adm-hours b { font-size: 10.5px; font-weight: 600; color: inherit; opacity: .8; }\n.adm-hours span { font-size: 13px; font-weight: 700; }\n\n.adm-funnel { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px; }\n.adm-funnel-step { position: relative; display: flex; flex-direction: column; gap: 4px; padding: 16px; border-radius: 12px; background: #f4f8fc; border: 1px solid #e2ebf5; }\n.adm-funnel-step strong { font-size: 26px; line-height: 1; color: var(--ink); font-weight: 700; }\n.adm-funnel-step span { font-size: 13px; color: #475569; font-weight: 600; }\n.adm-funnel-step small { font-size: 12px; color: var(--green); font-weight: 600; }\n.adm-funnel-step.muted { background: #fafafa; border-style: dashed; }\n.adm-funnel-step:not(.muted):not(:first-child)::before { content: "›"; position: absolute; left: -11px; top: 50%; transform: translateY(-50%); font-size: 20px; color: var(--soft); }\n\n/* tabelas */\n.adm-scroll { overflow-x: auto; margin: 0 -6px; padding: 0 6px; }\n.adm-scroll.tall { max-height: 520px; overflow-y: auto; }\n.adm-table { width: 100%; border-collapse: collapse; font-size: 13px; }\n.adm-table th { position: sticky; top: 0; padding: 9px 12px; text-align: left; font-size: 11px; font-weight: 700; color: var(--mut); text-transform: uppercase; letter-spacing: .05em; background: #f8fafc; white-space: nowrap; }\n.adm-table th:first-child { border-radius: 8px 0 0 8px; }\n.adm-table th:last-child { border-radius: 0 8px 8px 0; }\n.adm-table td { padding: 11px 12px; border-bottom: 1px solid #f1f5f9; color: #334155; vertical-align: middle; }\n.adm-table tr:last-child td { border-bottom: 0; }\n.adm-table tbody tr:hover td { background: #fafcff; }\n.adm-table td.adm-empty { padding: 16px 12px; }\n.adm-mini { display: inline-block; width: 64px; height: 6px; margin-right: 8px; border-radius: 99px; background: #eef2f6; vertical-align: middle; overflow: hidden; }\n.adm-mini.wide { width: 140px; }\n.adm-mini div { height: 100%; border-radius: 99px; background: var(--blue); }\n.adm-tag { display: inline-block; padding: 3px 9px; border-radius: 99px; background: #eef2f6; color: #475569; font-size: 11px; font-weight: 700; white-space: nowrap; }\n.adm-tag.t-whatsapp { background: #dcfce7; color: #15803d; }\n.adm-tag.t-phone { background: #e0f2fe; color: #0369a1; }\n.adm-tag.t-maps { background: #fef3c7; color: #b45309; }\n.adm-tag.t-download { background: #ede9fe; color: #6d28d9; }\n.adm-btn, .adm-wa { display: inline-flex; align-items: center; gap: 6px; height: 36px; padding: 0 14px; border-radius: 10px; background: var(--blue); color: #fff !important; font-weight: 600; font-size: 13px; text-decoration: none; white-space: nowrap; }\n.adm-wa { height: 28px; padding: 0 12px; border-radius: 8px; background: #25D366; font-size: 12px; }\n.adm-foot { margin: 8px 0 0; text-align: center; font-size: 12px; color: var(--soft); }\n\n.adm-login { min-height: 100vh; display: grid; place-items: center; padding: 20px; }\n.adm-login-card { width: min(380px, 100%); display: grid; gap: 14px; padding: 32px 28px; border-radius: 16px; background: #fff; border: 1px solid #e6ebf1; box-shadow: 0 12px 40px rgba(15, 42, 71, .08); }\n.adm-login-card label { display: grid; gap: 6px; }\n.adm-login-card label span { font-size: 12px; font-weight: 700; color: #334155; }\n.adm-login-card input { height: 46px; padding: 0 14px; border: 1px solid #cbd5e1; border-radius: 10px; font: inherit; font-size: 15px; }\n.adm-login-card button { height: 46px; border: 0; border-radius: 10px; background: #0057c8; color: #fff; font: inherit; font-weight: 700; cursor: pointer; }\n.adm-error { margin: 0; color: #b91c1c; font-size: 13px; }\n\n\n@media (max-width: 1100px) {\n  .adm-kpis { grid-template-columns: repeat(2, minmax(0, 1fr)); }\n  .adm-insights { grid-template-columns: repeat(2, minmax(0, 1fr)); }\n  .adm-grid2.wide-left { grid-template-columns: 1fr; }\n}\n@media (max-width: 800px) {\n  .adm-wrap { padding: 16px 12px 40px; }\n  .adm-grid2 { grid-template-columns: 1fr; }\n  .adm-strip { grid-template-columns: repeat(2, minmax(0, 1fr)); }\n  .adm-strip > div:nth-child(odd) { border-left: 0; }\n  .adm-strip > div:nth-child(n+3) { border-top: 1px solid var(--line); }\n  .adm-insights { grid-template-columns: 1fr; }\n  .adm-hours { grid-template-columns: repeat(6, minmax(0, 1fr)); }\n  .adm-funnel { grid-template-columns: repeat(2, minmax(0, 1fr)); }\n  .adm-funnel-step::before { display: none; }\n  .adm-cols { height: 150px; }\n  .adm-col span { display: none; }\n  .adm-col { padding-bottom: 0; }\n  .adm-top > * { min-width: 0; max-width: 100%; }\n  .adm-filters { width: 100%; }\n  .adm-range { overflow-x: auto; max-width: 100%; }\n  .adm-month select { max-width: 150px; }\n  .adm-kpi strong { font-size: 28px; }\n  .adm-card { padding: 16px; }\n}\n@media (max-width: 480px) { .adm-kpis { grid-template-columns: 1fr; } }\n\n.adm { overflow-x: clip; }\n'
